// ignore_for_file: depend_on_referenced_packages, avoid_print

/// Standalone lint rule scanner that runs saropa_lints rules against
/// any Dart project without requiring the target to have saropa_lints
/// as a dependency.
///
/// Reads the project's `analysis_options.yaml` (generated by `init`)
/// to determine which rules to run. When [tier] is set, the tier's rule
/// union is the starting point instead of the config's `diagnostics:`
/// section, but any `diagnostics:` overrides present are still layered on
/// top. If no config exists and no tier is set, returns null to signal the
/// caller to prompt the user to run `init` first.
library;

import 'dart:io' as io;
import 'dart:async' show unawaited;

import 'package:analyzer/analysis_rule/rule_context.dart';
import 'package:analyzer/dart/analysis/analysis_context.dart';
import 'package:analyzer/dart/analysis/analysis_context_collection.dart';
import 'package:analyzer/dart/analysis/results.dart';
import 'package:analyzer/dart/analysis/utilities.dart';
import 'package:analyzer/dart/ast/ast.dart' show AstVisitor, CompilationUnit;
import 'package:analyzer/error/listener.dart';
import 'package:analyzer/file_system/physical_file_system.dart';
import 'package:analyzer/source/file_source.dart';
import 'package:path/path.dart' as p;

import '../config/memory_mode.dart' show MemoryModeConfig;
import '../config/runtime_tier_cap.dart';
import '../init/cli_args.dart' show tierOrder;
import '../../saropa_lints.dart';
import 'capturing_registry.dart';
import 'parallel_scan_engine.dart';
import 'scan_config.dart';
import 'scan_jobs.dart' show defaultMaxMemoryMb, readAvailableMemoryMb;
import 'scan_pressure.dart' show PressureLimits;
import 'scan_diagnostic.dart';
import 'scan_rule_context.dart';
import 'scan_rule_tracer.dart';
import 'stale_ignore_probe.dart' show StaleIgnoreCoverage;
import 'scan_walker.dart';

/// Optional sink for progress and error messages. When null, output goes
/// to stdout (messages) and stderr (progress). When set, all output is
/// sent to this callback so callers can suppress or redirect.
typedef ScanMessageSink = void Function(String message);

/// Scans Dart files using saropa_lints rules without the plugin framework.
///
/// **Issue cap:** By default, [ProgressTracker] caps non-ERROR diagnostics at
/// 500 for IDE Problems-tab performance. CLI tools that need complete output
/// (accuracy report, audit) must pass [disableIssueCap] `= true` — otherwise
/// rules silently appear "silent" after 500 issues are reached.
class ScanRunner {
  ScanRunner({
    required this.targetPath,
    this.dartFiles,
    this.tier,
    this.enabledRuleNames,
    this.messageSink,
    this.applyExclusionsToFileList = true,
    this.debugRule,
    this.excludeLightLane = false,
    this.bypassTierCap = false,
    this.lane = RuleLane.full,
    this.laneStats = false,
    this.disableIssueCap = false,
    this.maxIssues,
    this.noExclude = false,
    List<String> excludeGlobs = const [],
    List<String> includeGlobs = const [],
    this.leaveStopSentinel = false,
    List<String>? preResolvedFiles,
  }) : _preResolvedFiles = preResolvedFiles,
       _rawExcludeGlobs = List.unmodifiable(excludeGlobs),
       _rawIncludeGlobs = List.unmodifiable(includeGlobs),
       _excludePatterns = excludeGlobs.map(_globToRegex).toList(),
       _includePatterns = includeGlobs.map(_globToRegex).toList();

  /// Raw glob strings kept so [runParallel] can rebuild an equivalent runner
  /// inside each worker isolate (compiled [RegExp]s are not worth sending).
  final List<String> _rawExcludeGlobs;
  final List<String> _rawIncludeGlobs;

  /// When true, a `.saropa_stop` sentinel is honored but NOT deleted. Worker
  /// isolates use this so every shard sees the stop request; the parent
  /// deletes the file once all workers have finished.
  final bool leaveStopSentinel;

  /// Exact file strings to scan, bypassing discovery, normalization and
  /// exclusion. Worker isolates get the parent's already-resolved list so the
  /// paths rules see are byte-identical to a serial run (some rules branch on
  /// path shape, so re-absolutizing would change results).
  final List<String>? _preResolvedFiles;

  /// Project root: config is loaded from here and relative [dartFiles] are resolved against it.
  final String targetPath;

  /// Optional explicit list of Dart files to scan. When null or empty, files are discovered under [targetPath].
  final List<String>? dartFiles;

  /// Optional tier name (e.g. `essential`, `recommended`, `pedantic`). When set,
  /// the rule set starts from this tier's union; the project's `diagnostics:`
  /// section (if present) is still layered on top, so a rule the user
  /// explicitly disabled stays disabled even though the tier includes it.
  final String? tier;

  /// Optional explicit set of rule names to enable, bypassing both [tier] and
  /// the project config. Takes precedence over [tier] when both are set. Lets a
  /// caller exercise a rule set that no single tier expresses — notably the
  /// union of every defined rule *including* stylistic rules, which no tier
  /// (not even `pedantic`) contains. Used by the accuracy report so that
  /// stylistic-tier rules are actually run and not falsely reported as silent.
  final Set<String>? enabledRuleNames;

  /// Optional sink for all messages. When null, messages go to stdout and progress to stderr.
  final ScanMessageSink? messageSink;

  /// When [dartFiles] is provided, whether to apply the same exclusions as directory discovery (e.g. `.g.dart`, `build/`). Default true.
  final bool applyExclusionsToFileList;

  /// When set, emits per-node trace output for the named rule, showing type
  /// resolution details at each visited AST node.
  final String? debugRule;

  /// Compiled glob patterns from `--exclude-globs` for user-specified path
  /// exclusions beyond the hardcoded defaults. Built once at construction from
  /// the raw glob strings so matching is a hot-path regex check, not a
  /// per-file glob parse. See #313.
  final List<RegExp> _excludePatterns;

  /// Compiled glob patterns from `--include-globs` that override the hardcoded
  /// exclusions. When a path matches both a hardcoded exclusion AND an include
  /// pattern, the include wins — letting users force-scan paths the defaults
  /// would skip (e.g. auditing third-party plugins in ephemeral dirs).
  final List<RegExp> _includePatterns;

  /// When true, disables ALL hardcoded path exclusions (example/, build/,
  /// .dart_tool/, generated patterns, etc.) so every discovered .dart file
  /// is scanned. User-supplied --exclude-globs still apply.
  final bool noExclude;

  /// Drops light-lane rules from the scan's rule set.
  ///
  /// Set by the scan daemon when the project's in-process plugin is running
  /// the light lane: those rules already produce live analyzer squiggles, so
  /// scanning them again would report every severe finding twice in the
  /// Problems panel — once as an analyzer diagnostic and once from the
  /// extension's own `DiagnosticCollection`. Membership comes from the shared
  /// predicate in `lib/src/config/rule_lane.dart`, so the two sides cannot
  /// disagree about which rules the split covers.
  final bool excludeLightLane;

  /// Skips `RuntimeTierCap.filterRuleSet()` in `_prepare()`, allowing
  /// the full `enabledRuleNames` set to run uncapped. Used by the audit
  /// CLI which must exercise every rule regardless of the project's
  /// configured tier.
  final bool bypassTierCap;

  /// Which lane the scan should use. Defaults to [RuleLane.full] so every
  /// enabled rule fires. Set to [RuleLane.light] via `--lane light` to
  /// restrict the scan to the same cheap, resolution-free subset the
  /// analysis server runs in its default lane.
  final RuleLane lane;

  /// When true, prints how many rules are in the light lane vs full-only,
  /// making the lane gate's effect observable. Activated by `--lane-stats`.
  final bool laneStats;

  /// Disables the IDE Problems-tab issue cap (`ProgressTracker._maxIssues`)
  /// so every diagnostic reaches the listener. The 500-issue default is
  /// designed for live IDE analysis, not CLI batch scans where completeness
  /// matters (accuracy report, audit). Without this, non-ERROR diagnostics
  /// are silently dropped after 500 issues and rules appear "silent".
  final bool disableIssueCap;

  /// Cap on reported non-ERROR diagnostics (errors are never capped). `0` =
  /// unlimited; null = leave the process-wide default (500, the IDE
  /// Problems-tab safeguard) unless [disableIssueCap] is set. The scan CLI and
  /// daemon pass `0` by default: a silent cap makes `--fail-on-count`
  /// thresholds and CI reports wrong.
  final int? maxIssues;

  /// Applies [maxIssues] / [disableIssueCap] to the process-wide tracker and
  /// returns the effective cap (0 = unlimited).
  int _applyIssueCap() {
    // Counters are process-wide statics; a reused process (the scan daemon,
    // tests, a second run) must not inherit the previous run's count or a
    // cap would trip on the first file. The cap setting itself survives reset.
    ProgressTracker.reset();
    final explicit = maxIssues;
    if (explicit != null) {
      ProgressTracker.setMaxIssues(explicit);
    } else if (disableIssueCap) {
      ProgressTracker.setMaxIssues(0);
    }
    return ProgressTracker.maxIssues;
  }

  /// Tells the user when output was trimmed, and how to lift the cap.
  void _noteIssueCap(int cap, {int? dropped}) {
    if (cap <= 0) return;
    final trimmed = dropped != null
        ? dropped > 0
        : ProgressTracker.isLimitReached;
    if (!trimmed) return;
    _err(
      'Output limited to about $cap non-error issue(s)'
      '${dropped != null ? ' ($dropped more not shown)' : ''}. '
      'Errors are never capped. Use --max-issues 0 (or a larger number) to '
      'see everything.',
    );
  }

  /// Map from rule name to its declared LintImpact name (error/warning/info).
  /// Built by `_prepare` so [_collectDiagnostics] can stamp each diagnostic.
  Map<String, String> _ruleImpactMap = const {};

  /// Files skipped because they fell outside the analysis context root during
  /// a resolved scan. The CLI checks this after the scan to exit non-zero when
  /// explicitly requested files could not be analyzed.
  int _skippedFileCount = 0;

  /// Number of files skipped for being outside the analysis context root.
  int get skippedFileCount => _skippedFileCount;

  /// Rules the last run actually instantiated (after tier, lane and config
  /// gating). The accepted-findings stale check uses it so an entry for a
  /// rule that did not run is never reported as stale.
  Set<String> get ranRuleNames => _ruleImpactMap.keys.toSet();

  /// Files whose rule walk finished in the last run (paths as scanned). A
  /// file that failed to resolve, was outside the roots, or was never
  /// reached (stop sentinel, memory limit) is absent. Filled by the
  /// in-process paths only, which is what the stale-ignore scan uses.
  Set<String> get walkedFiles => {..._walkedFiles};
  final Set<String> _walkedFiles = {};

  /// `StaleIgnoreCoverage.failureKey` pairs: a rule threw on that file and
  /// was disabled for the rest of its walk, so its silence there is not
  /// evidence.
  Set<String> get ruleFileFailures => {..._ruleFileFailures};
  final Set<String> _ruleFileFailures = {};

  /// Rules that registered at least one visitor in the last run. Narrower
  /// than [ranRuleNames]: a rule whose registration threw or added no
  /// visitor is in the plan but never looks at a node.
  Set<String> get registeredRuleNames => {..._registeredRuleNames};
  final Set<String> _registeredRuleNames = {};

  /// Builds an [AnalysisContextCollection] rooted at [projectRoot] for a
  /// long-lived caller (the scan daemon) to hold and reuse across many
  /// [runResolvedWithCollection] calls. This is the expensive step
  /// [runResolved] otherwise repeats on every invocation.
  static AnalysisContextCollection buildProjectCollection(String projectRoot) {
    return AnalysisContextCollection(
      includedPaths: [p.normalize(p.absolute(projectRoot))],
      resourceProvider: PhysicalResourceProvider.INSTANCE,
    );
  }

  /// Writes to stdout (via messageSink or print). Reserved for opt-in
  /// diagnostic output (--debug-rule trace). All progress/status messages
  /// must use `_err` so --format json stdout stays machine-parseable.
  void _debugOut(String message) {
    if (messageSink != null) {
      messageSink!(message);
    } else {
      print(message);
    }
  }

  void _err(String message) {
    if (messageSink != null) {
      messageSink!(message);
    } else {
      io.stderr.writeln(message);
    }
  }

  void _progress(String message) {
    if (messageSink != null) {
      messageSink!(message);
    } else {
      io.stderr.write(message);
    }
  }

  /// Runs the default syntactic scan and returns all diagnostics found.
  ///
  /// Returns `null` if no configuration was found and no [tier] was set (caller should tell
  /// the user to run `init` first), or if [tier] was set to an unknown value.
  ///
  /// This is a purely syntactic pass (`parseString`, no resolution): it is
  /// fast, but rules registered on `addInstanceCreationExpression` and any
  /// type-based rule under-report — see [runResolved] for the resolved path.
  List<ScanDiagnostic>? run() {
    // Reset per-run state for symmetry with the resolved paths — the
    // syntactic pass never calls contextFor so skips can't happen today,
    // but a reused ScanRunner must start clean regardless.
    _skippedFileCount = 0;
    final cap = _applyIssueCap();
    final plan = _prepare();
    if (plan == null) return null;
    if (plan.files.isEmpty) return const [];

    final registrations = _registerRules(
      plan.rules,
      () => ScanRuleContext(definingUnit: _dummyContextUnit()),
    );
    final result = _scanFiles(plan.files, registrations);
    _noteIssueCap(cap);
    return result;
  }

  /// Number of files a scan would visit, without loading any rules. Lets the
  /// CLI size the worker pool before [runParallel] starts.
  int countFilesToScan() => _resolveDartFiles().length;

  /// Report from the most recent [runParallel] (null before one ran).
  ParallelScanReport? lastParallelReport;

  /// Opens a reusable [ChunkScanner]: loads and registers the rules (and, when
  /// [resolved], builds the analyzer context collection) ONCE, then scans any
  /// number of file chunks against them. Used by worker isolates and by the
  /// in-process fallback of [runParallel]. Returns null when there is nothing
  /// to run (no rules enabled / unusable config).
  Future<ChunkScanner?> openChunkScanner({
    required bool resolved,
    int slowFileMs = 3000,
    bool rescueExcluded = false,
  }) async {
    final plan = _prepare();
    if (plan == null || plan.rules.isEmpty) return null;

    if (!resolved) {
      final registrations = _registerRules(
        plan.rules,
        () => ScanRuleContext(definingUnit: _dummyContextUnit()),
      );
      final visitorRule = _visitorRuleMap(registrations);
      return (files) async {
        final diagnostics = <ScanDiagnostic>[];
        final slow = <SlowFile>[];
        var stopped = false;
        for (final f in files) {
          if (_stopSentinelHit(0, 0, diagnostics.length)) {
            stopped = true;
            break;
          }
          final t = Stopwatch()..start();
          _scanSingleFile(f, registrations, visitorRule, diagnostics);
          if (t.elapsedMilliseconds >= slowFileMs) {
            slow.add(SlowFile(f, t.elapsedMilliseconds));
          }
        }
        return ChunkOutcome(
          diagnostics: diagnostics,
          stopped: stopped,
          slowFiles: slow,
        );
      };
    }

    // Resolved: one collection per scanner (per worker), built once.
    final collection = buildProjectCollection(targetPath);
    final registrations = _registerRules(
      plan.rules,
      () => ResolvedScanRuleContext(definingUnit: _dummyContextUnit()),
    );
    final visitorRule = _visitorRuleMap(registrations);
    return (files) async {
      final diagnostics = <ScanDiagnostic>[];
      final slow = <SlowFile>[];
      var stopped = false;
      var outsideRoots = 0;
      for (final raw in files) {
        if (_stopSentinelHit(0, 0, diagnostics.length)) {
          stopped = true;
          break;
        }
        final f = p.normalize(p.absolute(raw));
        AnalysisContext ctx;
        try {
          ctx = collection.contextFor(f);
        } on StateError {
          // The project's `analyzer: exclude:` removed this file. Mirror the
          // serial path: a file the caller explicitly asked for gets its own
          // single-file context; otherwise it is skipped (and counted).
          final rescued = rescueExcluded ? _contextForExcludedFile(f) : null;
          if (rescued == null) {
            outsideRoots++;
            continue;
          }
          ctx = rescued;
        }
        final t = Stopwatch()..start();
        await _scanSingleFileResolved(
          ctx,
          f,
          registrations,
          visitorRule,
          diagnostics,
        );
        if (t.elapsedMilliseconds >= slowFileMs) {
          slow.add(SlowFile(f, t.elapsedMilliseconds));
        }
      }
      return ChunkOutcome(
        diagnostics: diagnostics,
        stopped: stopped,
        slowFiles: slow,
        outsideRoots: outsideRoots,
      );
    };
  }

  /// Scans with [jobs] worker isolates (see `parallel_scan_engine.dart`):
  /// a chunk work queue with a memory/pressure watchdog, per-chunk timeouts
  /// and progress reporting. Output is identical for any worker count.
  ///
  /// [jobs] should come from `resolveJobs` (scan_jobs.dart). With [jobs] <= 1
  /// and no explicit engine request this is the plain in-process [run] /
  /// [runResolved]. Per-rule profiling and `--debug-rule` tracing keep
  /// process-local state: callers must use [run] for those.
  ///
  /// Read [lastParallelReport] afterwards for throttling, slow files and
  /// skipped files.
  Future<List<ScanDiagnostic>?> runParallel(
    int jobs, {
    bool resolve = false,
    ScanParallelConfig config = const ScanParallelConfig(),
  }) async {
    lastParallelReport = null;
    if (jobs <= 1 && !config.forceEngine) {
      return resolve ? runResolved() : run();
    }
    _skippedFileCount = 0;
    final plan = _prepare();
    if (plan == null) return null;
    if (plan.files.isEmpty) return const [];

    // Capture the cap in the parent: workers run with it disabled (their
    // per-process counters would drop diagnostics that belong in the global
    // first N); it is applied once after the ordered merge.
    final parentIssueCap = _applyIssueCap();
    final workerCount = jobs < 1 ? 1 : jobs;
    final limits = PressureLimits(
      maxMemoryMb:
          config.maxMemoryMb ??
          defaultMaxMemoryMb(
            jobs: workerCount,
            resolved: resolve,
            availableMemoryMb: config.availableMemoryMb,
          ),
      reserveMb:
          config.reserveMb ??
          PressureLimits.defaultReserveMb(config.totalMemoryMb),
    );
    _err(
      'Scanning ${plan.files.length} files with $workerCount '
      'worker${workerCount == 1 ? '' : 's'} '
      '(memory budget ${limits.maxMemoryMb} MB, keeping ${limits.reserveMb} MB '
      'free)...',
    );

    final spec = _WorkerSpec(
      targetPath: targetPath,
      tier: tier,
      enabledRuleNames: enabledRuleNames,
      excludeGlobs: _rawExcludeGlobs,
      includeGlobs: _rawIncludeGlobs,
      noExclude: noExclude,
      excludeLightLane: excludeLightLane,
      bypassTierCap: bypassTierCap,
      laneIsLight: lane == RuleLane.light,
      resolved: resolve,
      slowFileMs: config.slowFileMs,
      rescueExcluded: !applyExclusionsToFileList,
    );

    // The parent's own scanner, used only if workers cannot start.
    ChunkScanner? inline;
    Future<ChunkOutcome> inlineScan(List<String> files) async {
      inline ??= await openChunkScanner(
        resolved: resolve,
        slowFileMs: config.slowFileMs,
        rescueExcluded: !applyExclusionsToFileList,
      );
      final s = inline;
      if (s == null) return const ChunkOutcome(diagnostics: []);
      return s(files);
    }

    final result = await runChunkedScan(
      files: plan.files,
      options: ParallelScanOptions(
        jobs: workerCount,
        limits: limits,
        chunkTimeout: config.chunkTimeout,
        slowFileMs: config.slowFileMs,
        progress: config.progress,
        hasTerminal: config.hasTerminal,
        onMessage: _progressOrErr,
        chunkSize: config.chunkSize,
      ),
      spec: spec,
      workerEntry: _scanWorkerMain,
      inlineScan: inlineScan,
      readRssMb: _currentRssMb,
      readAvailableMb: readAvailableMemoryMb,
    );
    lastParallelReport = result.report;
    _skippedFileCount = result.report.outsideRoots;
    _reportParallelSummary(result.report);

    // The parent owns sentinel cleanup in parallel mode (workers leave it).
    final sentinel = io.File(p.join(p.absolute(targetPath), '.saropa_stop'));
    try {
      if (sentinel.existsSync()) sentinel.deleteSync();
    } on io.IOException {
      // Best effort; the scan itself already honored the stop.
    }

    // A serial run caps non-ERROR diagnostics (Problems-tab safeguard, see
    // ProgressTracker). Apply it once over the ordered merge so the result is
    // the same for every worker count.
    final out = <ScanDiagnostic>[];
    var nonError = 0;
    var dropped = 0;
    for (final d in result.diagnostics) {
      if (parentIssueCap > 0 && d.severity.toUpperCase() != 'ERROR') {
        nonError++;
        if (nonError > parentIssueCap + 1) {
          dropped++;
          continue;
        }
      }
      out.add(d);
    }
    _noteIssueCap(parentIssueCap, dropped: dropped);
    return out;
  }

  /// Progress and event lines: raw (no newline) to the sink or stderr.
  void _progressOrErr(String message) {
    if (message.startsWith('\r')) {
      _progress(message);
    } else {
      _err(message);
    }
  }

  int _currentRssMb() {
    try {
      return io.ProcessInfo.currentRss ~/ (1024 * 1024);
    } on Object {
      return 0;
    }
  }

  /// One-paragraph outcome for humans: what ran, what was throttled, what was
  /// slow or skipped.
  void _reportParallelSummary(ParallelScanReport r) {
    final secs = (r.elapsedMs / 1000).toStringAsFixed(1);
    _err(
      'Scanned ${r.filesScanned}/${r.filesTotal} files in ${secs}s '
      '(peak ${r.peakRssMb} MB'
      '${r.minAvailableMb != null ? ', lowest free ${r.minAvailableMb} MB' : ''}'
      '${r.usedFallback ? ', ran in-process' : ''}).',
    );
    if (r.throttleEvents.any((e) => e.to < e.from)) {
      _err(
        'The scan slowed itself down ${r.throttleEvents.where((e) => e.to < e.from).length} '
        'time(s) to protect your machine (lowest: ${r.minAllowedWorkers} '
        'worker(s)). Reduce --jobs or raise --max-memory-mb to change this.',
      );
    }
    if (r.slowFiles.isNotEmpty) {
      final top = r.slowFiles
          .take(3)
          .map((s) => '${s.path} (${(s.ms / 1000).toStringAsFixed(1)}s)')
          .join(', ');
      _err('Slowest files: $top.');
    }
    if (r.skippedFiles.isNotEmpty) {
      _err(
        '${r.skippedFiles.length} file(s) were NOT scanned because they hung '
        'or crashed a worker: ${r.skippedFiles.take(5).join(', ')}.',
      );
    }
    if (r.outsideRoots > 0) {
      _err(
        '${r.outsideRoots} file(s) were skipped (outside the analysis roots '
        'or excluded by the project config).',
      );
    }
    if (r.aborted) {
      _err('Scan stopped early: ${r.abortReason}. Results are partial.');
    }
  }

  /// Runs the scan with full type/element resolution and returns all
  /// diagnostics found. Returns `null` under the same no-config / unknown-tier
  /// conditions as [run].
  ///
  /// Resolution rewrites implicit constructor calls (`File('x')`) into
  /// `InstanceCreationExpression` nodes and supplies a real `typeProvider`/
  /// `typeSystem`, so rules that [run] silently misses fire here. The cost: it
  /// builds an [AnalysisContextCollection] and resolves each unit, which is
  /// materially slower and requires the target project to have had `pub get`
  /// run (otherwise units fail to resolve and are skipped with a message).
  Future<List<ScanDiagnostic>?> runResolved() async {
    // Reset per-run state so a reused ScanRunner doesn't carry stale counts.
    _skippedFileCount = 0;
    // Disable the Problems-tab cap when the caller requests complete output.
    final cap = _applyIssueCap();

    final plan = _prepare();
    if (plan == null) return null;
    if (plan.files.isEmpty) return const [];

    final registrations = _registerRules(
      plan.rules,
      () => ResolvedScanRuleContext(definingUnit: _dummyContextUnit()),
    );
    final result = await _scanFilesResolved(plan.files, registrations);
    _noteIssueCap(cap);
    return result;
  }

  /// Runs the resolved scan for [dartFiles] against an already-built
  /// [collection] instead of creating a new one.
  ///
  /// [runResolved] pays the cost of building an [AnalysisContextCollection]
  /// (full package-graph discovery, on the order of a minute on a large
  /// project) on every call — fine for a one-shot CLI invocation, ruinous for
  /// a save-triggered scan. A long-lived caller (the scan daemon) builds the
  /// collection once for the whole project and reuses it across requests;
  /// this method notifies the collection of the changed files via
  /// [AnalysisContext.changeFile]/[AnalysisContext.applyPendingFileChanges]
  /// so only the edited units are re-resolved, then scans them.
  Future<List<ScanDiagnostic>?> runResolvedWithCollection(
    AnalysisContextCollection collection,
  ) async {
    // Reset per-run state so a reused ScanRunner doesn't carry stale counts.
    _skippedFileCount = 0;
    // Disable the Problems-tab cap when the caller requests complete output.
    _applyIssueCap();

    final plan = _prepare();
    if (plan == null) return null;
    if (plan.files.isEmpty) return const [];

    // A file the target project's analyzer config excludes (or one outside
    // the collection's roots entirely) makes contextFor throw a StateError.
    // For a save-triggered daemon request that must degrade to a skip — the
    // user saved a file their own config says not to analyze — not an error
    // response, so partition the request into scannable files + skips first.
    // The resolved context is saved per file so _scanSingleFileResolved does
    // not need to repeat the lookup (#bug: redundant contextFor).
    final absFiles = <String>[];
    final fileContexts = <String, AnalysisContext>{};
    for (final f in plan.files.map(p.absolute).map(p.normalize)) {
      try {
        final ctx = collection.contextFor(f);
        ctx.changeFile(f);
        absFiles.add(f);
        fileContexts[f] = ctx;
      } on StateError {
        _err('  Skipping (outside analysis roots or excluded): $f');
        _skippedFileCount++;
      }
    }
    if (absFiles.isEmpty) return const [];
    // Deduplicate contexts — multiple files can share the same context.
    final affectedContexts = fileContexts.values.toSet();
    for (final ctx in affectedContexts) {
      await ctx.applyPendingFileChanges();
    }

    final registrations = _registerRules(
      plan.rules,
      () => ResolvedScanRuleContext(definingUnit: _dummyContextUnit()),
    );
    final diagnostics = <ScanDiagnostic>[];
    final visitorRule = _visitorRuleMap(registrations);
    for (final f in absFiles) {
      // absFiles only contains paths that passed the contextFor guard above,
      // so the lookup is guaranteed non-null. Assert to catch refactoring
      // mistakes that break the invariant.
      final ctx = fileContexts[f];
      assert(ctx != null, 'fileContexts missing entry for $f');
      if (ctx == null) continue;
      await _scanSingleFileResolved(
        ctx,
        f,
        registrations,
        visitorRule,
        diagnostics,
      );
    }
    return diagnostics;
  }

  /// Shared setup for both scan paths: resolves the enabled rule set and the
  /// file list, printing the same progress messages [run] historically did.
  ///
  /// Returns `null` only for the exit-2 conditions (no config and no tier, or
  /// an unknown tier). Otherwise returns the rules and files; an empty `files`
  /// list means "nothing to scan" (all rules disabled, or no Dart files found)
  /// and the caller returns no diagnostics.
  ({List<SaropaLintRule> rules, List<String> files})? _prepare() {
    MemoryModeConfig.markCli();
    // Coverage records describe one run only; a reused runner (daemon,
    // tests) must not carry the previous run's files or failures into the
    // stale-ignore check.
    _walkedFiles.clear();
    _ruleFileFailures.clear();
    _registeredRuleNames.clear();
    // The lane system limits in-process analysis server RSS by gating
    // expensive rules (usesTypeResolution, high cost, INFO severity) to the
    // full lane. The CLI scanner exits after one run, so RSS is irrelevant —
    // default to full coverage. Callers can pass RuleLane.light via --lane
    // to restrict the scan to the cheap subset.
    setActiveRuleLane(lane);
    reloadRuntimeTierCapFromProject(p.absolute(targetPath));
    // Reset before resolving, not after: _resolveRuleNames (via
    // _applyConfigOverrides / _loadRulesFromConfig) sets this when the
    // project has a diagnostics: section. Resetting afterward — the prior
    // order — always stomped that value back to null.
    SaropaLintRule.disabledRules = null;
    final resolved = _resolveRuleNames();
    if (resolved == null) return null;

    // Lane exclusion runs before the empty check so that "the light lane
    // covered everything you asked for" reports as nothing-to-scan rather
    // than scanning duplicates.
    // When bypassTierCap is true (audit mode), skip the tier cap filter so
    // every rule in enabledRuleNames runs regardless of the project's
    // configured tier.
    var ruleNames = bypassTierCap
        ? resolved
        : RuntimeTierCap.filterRuleSet(resolved);
    // Warn on the degenerate combination: --lane light keeps only light-lane
    // rules in the callback gate, while --exclude-light-lane removes those same
    // rules from the name set. The result is zero rules — not wrong, but almost
    // certainly not what the caller intended.
    if (excludeLightLane && lane == RuleLane.light) {
      _err(
        'Warning: --lane light combined with --exclude-light-lane '
        'leaves no rules to scan.',
      );
    }
    if (excludeLightLane) {
      // Light-lane membership is published as a side effect of the lazy
      // rule-registry build, which may not have happened yet. Without this
      // the set would still be empty here and the exclusion would silently
      // no-op into duplicate diagnostics.
      ensureRuleRegistryBuilt();
      final before = ruleNames.length;
      ruleNames = excludeLightLaneRules(ruleNames);
      // Progress message — stderr keeps stdout clean for JSON.
      _err(
        'Light lane excluded: $before → ${ruleNames.length} rules '
        '(the rest run live in the analysis server).',
      );
    }
    if (ruleNames.isEmpty) {
      _err('All rules are disabled in the configuration.');
      return (rules: const [], files: const []);
    }

    SaropaLintRule.enabledRules = ruleNames;
    final rules = getRulesFromRegistry(ruleNames);
    // Build the impact lookup so diagnostics carry the rule-declared impact.
    _ruleImpactMap = {
      for (final r in rules) r.code.lowerCaseName: r.impact.name,
    };
    // Copy nullable to local so promotion applies (avoid_nullable_interpolation).
    final tierLabel = tier;
    // Progress messages go to stderr so --format json stdout stays valid JSON.
    if (tierLabel != null) {
      _err('Loaded ${rules.length} rules for tier: $tierLabel');
    } else {
      _err('Loaded ${rules.length} rules from analysis_options.yaml');
    }

    // --lane-stats: show how the lane gate partitions the loaded rules.
    if (laneStats) {
      ensureRuleRegistryBuilt();
      final lightNames = lightLaneRuleNames;
      final lightCount = ruleNames.where((n) => lightNames.contains(n)).length;
      final fullOnly = ruleNames.length - lightCount;
      _err(
        'Lane stats: ${ruleNames.length} enabled, '
        '$lightCount light-lane, $fullOnly full-only. '
        'Active lane: ${lane.name}.',
      );
      // In light lane, list which rules are blocked so the caller can see
      // exactly what they're missing — this would have caught the original
      // bug where the CLI silently defaulted to light.
      if (lane == RuleLane.light) {
        final blocked = ruleNames.where((n) => !lightNames.contains(n)).toList()
          ..sort();
        if (blocked.isNotEmpty) {
          _err('Blocked by light lane (${blocked.length}):');
          for (final name in blocked) {
            _err('  - $name');
          }
        }
      }
    }

    final filesToScan = _resolveDartFiles();
    if (filesToScan.isEmpty) {
      _err('No .dart files found in: $targetPath');
      return (rules: rules, files: const []);
    }
    _err('Scanning ${filesToScan.length} files...');
    return (rules: rules, files: filesToScan);
  }

  RuleContextUnit _dummyContextUnit() =>
      _createContextUnit('', p.absolute(targetPath));

  /// Resolves enabled rule names: from [tier] if set (validated via [tierOrder]), otherwise from project config.
  Set<String>? _resolveRuleNames() {
    // An explicit rule set wins over tier/config: it is the only way to run a
    // set no tier expresses (e.g. all rules including stylistic).
    final explicit = enabledRuleNames;
    if (explicit != null) return explicit;

    // Copy nullable to local for field promotion (avoid_nullable_interpolation).
    final tierLabel = tier;
    if (tierLabel != null) {
      final normalized = tierLabel.toLowerCase();
      if (!tierOrder.contains(normalized)) {
        _err(
          "Unknown tier: '$tierLabel'. Valid tiers: ${tierOrder.join(', ')}",
        );
        return null;
      }
      return _applyConfigOverrides(getRulesForTier(normalized));
    }
    return _loadRulesFromConfig();
  }

  /// Layers the project's `diagnostics:` overrides on top of [tierRules]: a
  /// rule the user explicitly turned off stays off even though the tier
  /// includes it, and a rule they explicitly turned on runs even if the tier
  /// wouldn't otherwise enable it. Silently a no-op when the project has no
  /// `diagnostics:` section (e.g. the scan-on-save daemon on a project that
  /// never ran `init`).
  Set<String> _applyConfigOverrides(Set<String> tierRules) {
    final config = loadScanConfig(p.absolute(targetPath));
    if (config == null) return tierRules;

    SaropaLintRule.disabledRules = config.disabledRules.isEmpty
        ? null
        : config.disabledRules;
    return tierRules
        .difference(config.disabledRules)
        .union(config.enabledRules);
  }

  /// Loads enabled rules from the project's analysis_options.yaml.
  ///
  /// Returns null if no config file or no diagnostics section found.
  Set<String>? _loadRulesFromConfig() {
    final config = loadScanConfig(p.absolute(targetPath));
    if (config == null) {
      final absPath = p.absolute(targetPath);
      _err('No saropa_lints configuration found in:');
      _err('  $absPath/analysis_options.yaml');
      _err('');
      _err('Run init first to configure rules:');
      _err('  dart run saropa_lints init --target $absPath');
      return null;
    }

    SaropaLintRule.disabledRules = config.disabledRules.isEmpty
        ? null
        : config.disabledRules;
    return config.enabledRules;
  }

  /// Resolves files to scan: [dartFiles] if non-empty (relative paths resolved
  /// against [targetPath], exclusions applied when [applyExclusionsToFileList]);
  /// otherwise discovers under [targetPath]. User-supplied `--exclude-globs`
  /// patterns are applied in both paths.
  List<String> _resolveDartFiles() {
    final pre = _preResolvedFiles;
    if (pre != null) return pre;
    final raw = dartFiles;
    if (raw == null || raw.isEmpty) {
      // Pass noExclude so --no-exclude skips hardcoded path exclusions
      // (example/, .dart_tool/, build/, etc.) during directory discovery.
      // Absolute, because project lookup, baselines, `// ignore:` matching and
      // path-shaped rules all compare against absolute roots: `scan .` used to
      // hand them `./lib/a.dart` and apply none of them. Done after discovery
      // so exclusions still judge the path as the caller gave it.
      return _findDartFiles(
        targetPath,
        _excludePatterns,
        _includePatterns,
        noExclude,
      ).map((f) => p.normalize(p.absolute(f))).toList();
    }
    final root = p.absolute(targetPath);
    var list = raw
        .where((path) => path.trim().isNotEmpty)
        .map(
          (path) => p.isAbsolute(path)
              ? p.normalize(path)
              : p.normalize(p.join(root, path)),
        )
        .where((path) => path.endsWith('.dart'))
        .toList();
    if (applyExclusionsToFileList) {
      // Combined exclusion/inclusion filter: _shouldInclude handles the
      // hardcoded defaults, user-supplied exclude-globs, and include-glob
      // overrides in one pass.
      // --no-exclude bypasses hardcoded exclusions even when applying
      // exclusions to an explicit file list.
      list = list
          .where(
            (path) => _shouldInclude(
              path,
              _excludePatterns,
              _includePatterns,
              noExclude,
              targetPath,
            ),
          )
          .toList();
    }
    return list;
  }

  /// Registers each rule's node visitors against a fresh context produced by
  /// [contextFactory]. The factory varies by scan path ([ScanRuleContext] for
  /// the syntactic pass, [ResolvedScanRuleContext] for `--resolve`); the rest
  /// of the registration loop is identical.
  List<_RuleRegistration> _registerRules(
    List<SaropaLintRule> rules,
    MutableRuleContext Function() contextFactory,
  ) {
    final result = <_RuleRegistration>[];

    for (final rule in rules) {
      final registry = CapturingRuleVisitorRegistry();
      final context = contextFactory();

      try {
        rule.registerNodeProcessors(registry, context);
      } on Object catch (e) {
        _err('  Skipping ${rule.code.lowerCaseName}: $e');
        continue;
      }

      var visitors = registry.capturedVisitors;
      if (visitors.isEmpty) continue;

      final dbg = debugRule;
      if (dbg != null && rule.code.lowerCaseName == dbg) {
        _debugOut(
          'DEBUG: tracing rule "$dbg" '
          '(${visitors.length} visitor(s))',
        );
        visitors = visitors
            .map(
              (v) =>
                  TracingVisitorWrapper(v as AstVisitor<void>, _debugOut, dbg),
            )
            .toList();
      }

      if (visitors.isNotEmpty) {
        result.add(_RuleRegistration(rule, visitors.cast(), context));
        // Only a rule that reached this point can have looked at a node.
        _registeredRuleNames.add(rule.code.lowerCaseName);
      }
    }

    return result;
  }

  List<ScanDiagnostic> _scanFiles(
    List<String> files,
    List<_RuleRegistration> registrations,
  ) {
    final diagnostics = <ScanDiagnostic>[];
    final sw = Stopwatch()..start();
    final visitorRule = _visitorRuleMap(registrations);

    for (var i = 0; i < files.length; i++) {
      // Abort hook: a `.saropa_stop` file in the scan target root stops the
      // walk between files. This must live HERE — the historical sentinel
      // path (SaropaLintRule._checkAbortSentinel) keys on
      // AnalysisReporter.projectRoot, which is null in the scan CLI, so it
      // never fired; and even when armed it only no-ops rule callbacks
      // without ending the file loop, leaving long scans unkillable except
      // by killing the process (which loses the report and timing profile).
      if (_stopSentinelHit(i, files.length, diagnostics.length)) break;
      _showProgress(i, files.length, diagnostics.length, files[i], sw);
      _scanSingleFile(files[i], registrations, visitorRule, diagnostics);
    }

    // Clear progress line when using stderr
    if (messageSink == null) {
      io.stderr.write('\r${' ' * 79}\r');
    }
    return diagnostics;
  }

  /// True when the user dropped a `.saropa_stop` file in the scan target
  /// root, requesting the scan stop early with a partial report.
  ///
  /// Checked once per file — a single `existsSync` is trivial next to the
  /// ~100ms of rule work an average file costs, and per-file checking keeps
  /// abort latency at one file instead of one batch. The sentinel is deleted
  /// on detection so the NEXT scan does not instantly abort on the leftover
  /// file; a delete failure (e.g. permissions) still aborts, because honoring
  /// the user's stop request matters more than the cleanup.
  bool _stopSentinelHit(int scanned, int total, int issueCount) {
    final sentinel = io.File(p.join(p.absolute(targetPath), '.saropa_stop'));
    try {
      if (!sentinel.existsSync()) return false;
    } on io.IOException {
      // Unreadable sentinel state: keep scanning rather than abort on an OS
      // error the user never asked for.
      return false;
    }
    try {
      if (!leaveStopSentinel) sentinel.deleteSync();
    } on io.IOException {
      // Leave the stale sentinel; the abort itself still proceeds.
    }
    // Abort notice goes to stderr so stdout stays valid JSON.
    _err(
      '[saropa_lints] Scan aborted by .saropa_stop after '
      '$scanned/$total files ($issueCount issues so far). '
      'Partial report follows.',
    );
    return true;
  }

  void _scanSingleFile(
    String filePath,
    List<_RuleRegistration> registrations,
    Map<AstVisitor<void>, String> visitorRule,
    List<ScanDiagnostic> diagnostics,
  ) {
    final content = io.File(filePath).readAsStringSync();
    final unit = parseString(
      content: content,
      path: filePath,
      throwIfDiagnostics: false,
    ).unit;

    final listener = RecordingDiagnosticListener();
    final source = FileSource(
      PhysicalResourceProvider.INSTANCE.getFile(filePath),
    );
    final reporter = DiagnosticReporter(listener, source);
    final ctxUnit = _createContextUnit(content, filePath, unit: unit);

    final allVisitors = <AstVisitor<void>>[];
    for (final reg in registrations) {
      reg.context.currentUnit = ctxUnit;
      reg.rule.reporter = reporter;
      allVisitors.addAll(reg.visitors);
    }

    if (allVisitors.isNotEmpty) {
      unit.accept(
        ScanWalker(
          allVisitors,
          onError: _onVisitorError(visitorRule, filePath),
        ),
      );
    }

    _collectDiagnostics(listener, unit, filePath, diagnostics);
    // The walk finished: this file counts as covered for the stale check.
    _walkedFiles.add(filePath);
  }

  /// Maps each registered visitor back to its rule name so a visitor that
  /// throws mid-walk can be reported by name.
  Map<AstVisitor<void>, String> _visitorRuleMap(
    List<_RuleRegistration> registrations,
  ) {
    final map = <AstVisitor<void>, String>{};
    for (final reg in registrations) {
      final name = reg.rule.code.lowerCaseName;
      for (final v in reg.visitors) {
        map[v] = name;
      }
    }
    return map;
  }

  /// Builds the per-file error sink passed to [ScanWalker]. A rule that throws
  /// is reported (rule name + file) and disabled for the rest of that file's
  /// walk, so one buggy rule never aborts the whole scan.
  ScanVisitorError _onVisitorError(
    Map<AstVisitor<void>, String> visitorRule,
    String filePath,
  ) {
    return (visitor, error, stackTrace) {
      final rule = visitorRule[visitor] ?? 'unknown_rule';
      _err('  Rule "$rule" failed on ${p.basename(filePath)}: $error');
      // The rule is off for the rest of this file, so its missing findings
      // there must not make an ignore comment look stale.
      _ruleFileFailures.add(StaleIgnoreCoverage.failureKey(filePath, rule));
    };
  }

  /// Fallback RSS ceiling (MB) for the between-files scan check, used only
  /// when no hard limit is configured via [MemoryPressureHandler] (e.g. the
  /// scan CLI running standalone, outside the plugin's memory-mode config).
  /// 1500 MB leaves headroom below typical OOM territory for a Dart process
  /// while still catching runaway scans over very large codebases.
  static const int _defaultScanRssLimitMb = 1500;

  /// Resolves and scans [files] one at a time, returning all diagnostics.
  ///
  /// A single [AnalysisContextCollection] spans every file so the analyzer's
  /// per-context caches are reused across the run. Paths are absolutized
  /// because the analyzer requires absolute, normalized paths.
  Future<List<ScanDiagnostic>> _scanFilesResolved(
    List<String> files,
    List<_RuleRegistration> registrations,
  ) async {
    final diagnostics = <ScanDiagnostic>[];
    final sw = Stopwatch()..start();
    final visitorRule = _visitorRuleMap(registrations);

    final absFiles = files.map(p.absolute).map(p.normalize).toList();
    // Root the collection at the PROJECT DIRECTORY, not at individual files.
    // AnalysisContextCollection builds a full package-graph context per
    // included path — passing N files creates N redundant contexts, blowing
    // RSS past the limit before even one file is scanned (#402). A single
    // project root shares one context across all files.
    final collection = AnalysisContextCollection(
      includedPaths: [p.normalize(p.absolute(targetPath))],
      resourceProvider: PhysicalResourceProvider.INSTANCE,
    );

    // RSS ceiling for the between-files check below. Prefer the hard limit
    // already configured on MemoryPressureHandler (e.g. via
    // SAROPA_LINTS_MAX_RSS_MB or memory_mode) so the scan CLI and the
    // in-editor plugin agree on one threshold; fall back to a fixed default
    // when nothing is configured, so standalone scan runs are still
    // protected from OOM on very large codebases.
    final scanRssLimitMb = MemoryPressureHandler.hardRssLimitMb > 0
        ? MemoryPressureHandler.hardRssLimitMb
        : _defaultScanRssLimitMb;

    for (var i = 0; i < absFiles.length; i++) {
      // A file outside the collection's root (e.g. an explicit path pointing
      // elsewhere) makes contextFor throw StateError — skip it rather than
      // crashing the entire scan.
      AnalysisContext fileContext;
      try {
        fileContext = collection.contextFor(absFiles[i]);
      } on StateError {
        // The project's own `analyzer: exclude:` (e.g. `example/**`) removes
        // a file from the shared collection. When the caller explicitly
        // disabled exclusions for the file list
        // ([applyExclusionsToFileList] false) it still asked for that file to
        // be scanned, so honoring the exclude here made the resolved scan
        // silently return nothing while the syntactic run() scanned it —
        // violating the resolved-superset-of-syntactic invariant. Give such
        // a file its own single-file collection (explicitly included paths
        // are not subject to the exclude globs). Cost is one extra context,
        // paid only for explicitly requested excluded files.
        final rescued = applyExclusionsToFileList
            ? null
            : _contextForExcludedFile(absFiles[i]);
        if (rescued == null) {
          _err('  Skipping (outside analysis roots): ${absFiles[i]}');
          _skippedFileCount++;
          continue;
        }
        fileContext = rescued;
      }
      _showProgress(i, absFiles.length, diagnostics.length, absFiles[i], sw);
      await _scanSingleFileResolved(
        fileContext,
        absFiles[i],
        registrations,
        visitorRule,
        diagnostics,
      );

      // Check RSS between files to avoid OOM during large scans. Resolved
      // ASTs and analyzer caches accumulate per file, so a project with
      // thousands of files can exhaust memory well before reaching the end
      // — sampling here lets the scan bail out with partial results (still
      // useful) instead of crashing with nothing. ProcessInfo.currentRss can
      // throw on platforms without RSS support; treat that as "unavailable"
      // (-1) rather than letting it crash the scan.
      int rssMb;
      try {
        rssMb = io.ProcessInfo.currentRss ~/ (1024 * 1024);
      } on Object {
        rssMb = -1;
      }
      if (rssMb > scanRssLimitMb) {
        final scanned = i + 1;
        final remaining = absFiles.length - scanned;
        _err(
          '  Scan RSS (${rssMb}MB) exceeds limit (${scanRssLimitMb}MB) after '
          '$scanned/${absFiles.length} files — stopping early '
          '($remaining files skipped).',
        );
        break;
      }
    }

    // Release per-file collections created for excluded files (see above).
    for (final rescuedCollection in _rescuedCollections) {
      await rescuedCollection.dispose();
    }
    _rescuedCollections.clear();

    // Clear progress line when using stderr
    if (messageSink == null) {
      io.stderr.write('\r${' ' * 79}\r');
    }
    return diagnostics;
  }

  /// Single-file collections built by [_contextForExcludedFile]; disposed when
  /// the resolved scan finishes so many excluded files do not keep one full
  /// analyzer context alive each.
  final List<AnalysisContextCollection> _rescuedCollections =
      <AnalysisContextCollection>[];

  /// Builds a context rooted at the single [absFile], or null when the
  /// analyzer still refuses it. Used only for files the project's analyzer
  /// excludes that the caller explicitly asked to scan.
  AnalysisContext? _contextForExcludedFile(String absFile) {
    try {
      final collection = AnalysisContextCollection(
        includedPaths: [absFile],
        resourceProvider: PhysicalResourceProvider.INSTANCE,
      );
      // Tracked so the scan can dispose it once finished.
      _rescuedCollections.add(collection);
      return collection.contextFor(absFile);
    } on StateError {
      // Still unreachable: caller reports it as skipped.
      return null;
    }
  }

  Future<void> _scanSingleFileResolved(
    AnalysisContext context,
    String filePath,
    List<_RuleRegistration> registrations,
    Map<AstVisitor<void>, String> visitorRule,
    List<ScanDiagnostic> diagnostics,
  ) async {
    // Context is resolved once by the caller — no redundant contextFor lookup.
    final session = context.currentSession;
    final result = await session.getResolvedUnit(filePath);
    // A file outside the resolved package, or one whose project lacks
    // `pub get`, resolves to an error result with no usable unit. Skip it with
    // a message rather than crashing or silently dropping it.
    if (result is! ResolvedUnitResult) {
      _err('  Skipping (could not resolve): $filePath');
      return;
    }

    final unit = result.unit;
    final listener = RecordingDiagnosticListener();
    final reporter = DiagnosticReporter(
      listener,
      FileSource(PhysicalResourceProvider.INSTANCE.getFile(filePath)),
    );
    final ctxUnit = RuleContextUnit(
      file: PhysicalResourceProvider.INSTANCE.getFile(filePath),
      content: result.content,
      diagnosticReporter: reporter,
      unit: unit,
    );

    final allVisitors = <AstVisitor<void>>[];
    for (final reg in registrations) {
      // The factory in runResolved only ever produces ResolvedScanRuleContext,
      // so this cast is safe; updating its resolution results per file is what
      // makes type-based rules see the current file rather than the first one.
      // Verified false positive: `context` here is this package's own
      // ResolvedScanRuleContext (rule-registration state), not Flutter's
      // BuildContext — there is no widget tree in this CLI tool. The scan
      // CLI's default syntactic pass (see ScanRunner.run doc) has no type
      // information to rule that out by itself, so avoid_context_across_async
      // matches on the identifier name alone at each `context.` use below.
      // ignore: avoid_context_across_async, avoid_unsafe_cast -- reg.context is always ResolvedScanRuleContext by construction
      final context = reg.context as ResolvedScanRuleContext;
      // ignore: avoid_context_across_async
      context.currentUnit = ctxUnit;
      // ignore: avoid_context_across_async
      context.setResolved(
        typeProvider: result.typeProvider,
        typeSystem: result.typeSystem,
        library: result.libraryElement,
      );
      reg.rule.reporter = reporter;
      allVisitors.addAll(reg.visitors);
    }

    if (allVisitors.isNotEmpty) {
      unit.accept(
        ScanWalker(
          allVisitors,
          onError: _onVisitorError(visitorRule, filePath),
        ),
      );
    }

    _collectDiagnostics(listener, unit, filePath, diagnostics);
    // Resolved and walked: covered for the stale check (an unresolved file
    // returned above and stays uncovered).
    _walkedFiles.add(filePath);
  }

  /// Converts recorded analyzer diagnostics into [ScanDiagnostic]s, resolving
  /// each offset to a line/column via the unit's line info. Shared by the
  /// syntactic and resolved scan paths.
  void _collectDiagnostics(
    RecordingDiagnosticListener listener,
    CompilationUnit unit,
    String filePath,
    List<ScanDiagnostic> diagnostics,
  ) {
    for (final d in listener.diagnostics) {
      final loc = unit.lineInfo.getLocation(d.offset);
      // End position lets the extension highlight the full diagnostic span
      // instead of a single character (which triggers "find all occurrences").
      final endLoc = unit.lineInfo.getLocation(d.offset + d.length);
      final ruleName = d.diagnosticCode.lowerCaseName;
      diagnostics.add(
        ScanDiagnostic(
          ruleName: ruleName,
          filePath: filePath,
          line: loc.lineNumber,
          column: loc.columnNumber,
          offset: d.offset,
          length: d.length,
          endLine: endLoc.lineNumber,
          endColumn: endLoc.columnNumber,
          severity: d.diagnosticCode.severity.name,
          problemMessage: d.problemMessage.messageText(includeUrl: false),
          // Look up the rule's declared impact; null for non-saropa diagnostics.
          impact: _ruleImpactMap[ruleName],
        ),
      );
    }
  }

  void _showProgress(
    int index,
    int total,
    int issues,
    String filePath,
    Stopwatch sw,
  ) {
    if (index % 10 != 0) return;
    final elapsed = sw.elapsedMilliseconds / 1000;
    final rate = elapsed > 0 ? (index / elapsed).round() : 0;
    final name = p.basename(filePath);
    _progress(
      '\r  Files: $index/$total | ${elapsed.toStringAsFixed(1)}s'
      ' | $rate/s | Issues: $issues | $name${' ' * 20}',
    );
  }

  /// Creates a [RuleContextUnit] for the given file content.
  static RuleContextUnit _createContextUnit(
    String content,
    String filePath, {
    CompilationUnit? unit,
  }) {
    final provider = PhysicalResourceProvider.INSTANCE;
    // PhysicalResourceProvider asserts on non-normalized paths. Callers can
    // hand in a mixed-separator path on Windows (e.g. `C:\tmp\x/packages`
    // from string-concatenated targets), which threw "Path must be
    // normalized". Normalizing here fixes it for every call site at once.
    final file = provider.getFile(p.normalize(filePath));
    final listener = RecordingDiagnosticListener();
    final reporter = DiagnosticReporter(listener, FileSource(file));
    return RuleContextUnit(
      file: file,
      content: content,
      diagnosticReporter: reporter,
      unit:
          unit ?? parseString(content: content, throwIfDiagnostics: false).unit,
    );
  }

  /// Public wrapper around [_findDartFiles] for callers that need the
  /// project's discovered file list up front (e.g. the scan daemon's
  /// `listFiles` request, which the IDE baseline scan uses to build chunked
  /// batches before issuing per-chunk resolved scans).
  ///
  /// Optional [excludeGlobs] / [includeGlobs] use the same matching as the
  /// CLI flags (relative to [directory], or the path as listed).
  static List<String> discoverDartFiles(
    String directory, {
    List<String> excludeGlobs = const [],
    List<String> includeGlobs = const [],
  }) => _findDartFiles(
    directory,
    excludeGlobs.map(_globToRegex).toList(),
    includeGlobs.map(_globToRegex).toList(),
  );

  /// Whether [path] matches one of [globs], with the same matching as
  /// `--exclude-globs` (as given, absolute, or relative to [root]). For callers
  /// that pick files outside discovery but must still honor the user's globs.
  static bool matchesAnyGlob(String path, List<String> globs, String root) =>
      _matchesExcludeGlob(path, globs.map(_globToRegex).toList(), root);

  static List<String> _findDartFiles(
    String directory, [
    List<RegExp> excludePatterns = const [],
    List<RegExp> includePatterns = const [],
    bool skipHardcodedExclusions = false,
  ]) {
    final dir = io.Directory(directory);
    if (!dir.existsSync()) return const [];

    final results = <String>[];
    _walkDartFiles(
      dir,
      excludePatterns,
      includePatterns,
      skipHardcodedExclusions,
      directory,
      results,
    );
    return results;
  }

  /// Walks [dir] one level at a time, skipping subdirectories that already
  /// match an exclude pattern instead of listing them (#408 — `listSync`'s
  /// built-in `recursive: true` enters every subdirectory before exclusions
  /// can apply, so a permission-denied directory under an excluded path
  /// crashes the scan with `PathAccessException` even when `--exclude-globs`
  /// was told to skip it).
  static void _walkDartFiles(
    io.Directory dir,
    List<RegExp> excludePatterns,
    List<RegExp> includePatterns,
    bool skipHardcodedExclusions,
    String root,
    List<String> results,
  ) {
    List<io.FileSystemEntity> entries;
    try {
      entries = dir.listSync();
    } on io.FileSystemException {
      // Permission-denied or otherwise unreadable directory: skip it rather
      // than aborting the whole scan.
      return;
    }
    for (final entry in entries) {
      if (entry is io.Directory) {
        // Mirror _shouldInclude's precedence at the directory level: an
        // include-glob can still force a descent into an otherwise-excluded
        // directory (e.g. `--include-globs "example/**"`), so only prune
        // when nothing would rescue it.
        final includeOverride = _matchesExcludeGlob(
          entry.path,
          includePatterns,
          root,
        );
        if (!includeOverride) {
          if (!skipHardcodedExclusions && _isExcluded(entry.path)) continue;
          if (_matchesExcludeGlob(entry.path, excludePatterns, root)) {
            continue;
          }
        }
        _walkDartFiles(
          entry,
          excludePatterns,
          includePatterns,
          skipHardcodedExclusions,
          root,
          results,
        );
      } else if (entry is io.File &&
          entry.path.endsWith('.dart') &&
          _shouldInclude(
            entry.path,
            excludePatterns,
            includePatterns,
            skipHardcodedExclusions,
            root,
          )) {
        results.add(p.normalize(entry.path));
      }
    }
  }

  /// Combined exclusion/inclusion check: a file is kept when it passes the
  /// hardcoded exclusions AND user-supplied exclude-globs, OR when it matches
  /// an include-glob (which overrides both). Include wins over exclude so
  /// users can force-scan paths the defaults would skip.
  /// When [skipHardcodedExclusions] is true (`--no-exclude`), the hardcoded
  /// `_isExcluded` check is bypassed entirely — only user-supplied
  /// exclude-globs can drop a file.
  static bool _shouldInclude(
    String path,
    List<RegExp> excludePatterns,
    List<RegExp> includePatterns, [
    bool skipHardcodedExclusions = false,
    String? root,
  ]) {
    // Include-globs override all exclusions — check first.
    if (_matchesExcludeGlob(path, includePatterns, root)) return true;
    // Normal exclusion chain: hardcoded defaults + user-supplied globs.
    if (!skipHardcodedExclusions && _isExcluded(path)) return false;
    if (_matchesExcludeGlob(path, excludePatterns, root)) return false;
    return true;
  }

  /// Paths that are never user code — build artifacts, generated files, and
  /// platform ephemeral directories (symlinked plugin sources the user can't
  /// control). See #313 for the ephemeral/.plugin_symlinks addition.
  static bool _isExcluded(String path) {
    final n = path.replaceAll('\\', '/');
    return n.contains('/.dart_tool/') ||
        n.contains('/build/') ||
        n.contains('/bin/') ||
        // Skip example directories — but match only the conventional `/example/`
        // and `/examples/` paths, not `/example_packages/` which holds
        // package-specific test fixtures that the scan CLI must be able to reach.
        n.contains('/example/') ||
        n.contains('/examples/') ||
        n.contains('/ephemeral/') ||
        n.contains('/.plugin_symlinks/') ||
        n.contains('.g.dart') ||
        n.contains('.freezed.dart') ||
        n.contains('.gr.dart') ||
        n.contains('.gen.dart') ||
        n.contains('.mocks.dart') ||
        n.contains('.config.dart') ||
        n.contains('/generated/');
  }

  /// Converts a simple glob pattern to a [RegExp] for path matching.
  ///
  /// Supports `**` (any path segments), `*` (any non-separator chars), and
  /// `?` (single non-separator char). Pattern is matched against the
  /// forward-slash-normalized path.
  static RegExp _globToRegex(String glob) {
    // Normalize Windows backslashes so patterns typed on Windows (e.g.
    // `windows\flutter\ephemeral\**`) match forward-slash-normalized paths.
    final normalized = glob.replaceAll('\\', '/');
    final buf = StringBuffer('^');
    var i = 0;
    while (i < normalized.length) {
      final c = normalized[i];
      if (c == '*') {
        // `**` matches any number of path segments (including separators).
        if (i + 1 < normalized.length && normalized[i + 1] == '*') {
          buf.write('.*');
          i += 2;
          // Skip a trailing slash after `**` so `**/foo` works naturally.
          if (i < normalized.length && normalized[i] == '/') i++;
          continue;
        }
        // Single `*` matches anything except `/`.
        buf.write('[^/]*');
      } else if (c == '?') {
        buf.write('[^/]');
      } else {
        // Escape regex metacharacters in the literal portion.
        buf.write(RegExp.escape(c));
      }
      i++;
    }
    buf.write(r'$');
    return RegExp(buf.toString(), caseSensitive: false);
  }

  /// Returns true if [path] matches any of the compiled [excludePatterns].
  ///
  /// Each pattern is tested against the path as given and, when [root] is
  /// set, against the path relative to [root] (forward slashes, no leading
  /// `./`), so `packages/**` works whether the scan path is `.` or absolute.
  static bool _matchesExcludeGlob(
    String path,
    List<RegExp> excludePatterns, [
    String? root,
  ]) {
    if (excludePatterns.isEmpty) return false;
    final normalized = path.replaceAll('\\', '/');
    String? relative;
    if (root != null) {
      final rel = p
          .relative(p.absolute(path), from: p.absolute(root))
          .replaceAll('\\', '/');
      if (rel != '..' && !rel.startsWith('../')) relative = rel;
    }
    // Absolute form too, so absolute globs (analyzer excludes, #403) match
    // when the scan target is relative.
    final absolute = p.absolute(path).replaceAll('\\', '/');
    return excludePatterns.any(
      (re) =>
          re.hasMatch(normalized) ||
          re.hasMatch(absolute) ||
          (relative != null && re.hasMatch(relative)),
    );
  }
}

class _RuleRegistration {
  const _RuleRegistration(this.rule, this.visitors, this.context);
  final SaropaLintRule rule;
  final List<AstVisitor<void>> visitors;

  /// The shared context for this rule. [ScanRuleContext] for the syntactic
  /// scan, [ResolvedScanRuleContext] for `--resolve`; both are
  /// [MutableRuleContext] so the runner can update [currentUnit] per file.
  final MutableRuleContext context;
}

/// Sendable description of a [ScanRunner] for a worker isolate (only plain
/// values: strings, bools, sets of strings).
class _WorkerSpec {
  const _WorkerSpec({
    required this.targetPath,
    required this.tier,
    required this.enabledRuleNames,
    required this.excludeGlobs,
    required this.includeGlobs,
    required this.noExclude,
    required this.excludeLightLane,
    required this.bypassTierCap,
    required this.laneIsLight,
    required this.resolved,
    required this.slowFileMs,
    required this.rescueExcluded,
  });

  final String targetPath;
  final String? tier;
  final Set<String>? enabledRuleNames;
  final List<String> excludeGlobs;
  final List<String> includeGlobs;
  final bool noExclude;
  final bool excludeLightLane;
  final bool bypassTierCap;
  final bool laneIsLight;
  final bool resolved;
  final int slowFileMs;
  final bool rescueExcluded;
}

/// Worker isolate entry point (top level so it can be spawned).
void _scanWorkerMain(WorkerBootstrap boot) {
  unawaited(
    runWorkerLoop(boot, (Object raw) async {
      final spec = raw as _WorkerSpec;
      // The Problems-tab cap counts per process, so a per-worker cap would
      // drop diagnostics that belong in the global first N. Workers report
      // everything; the parent applies the cap once after merging.
      ProgressTracker.setMaxIssues(0);
      ProgressTracker.suppressProgressOutput = true;
      final runner = ScanRunner(
        targetPath: spec.targetPath,
        // Chunks arrive over the port; discovery is the parent's job.
        preResolvedFiles: const [],
        tier: spec.tier,
        enabledRuleNames: spec.enabledRuleNames,
        // Worker output is silent by default (the parent owns the terminal);
        // set SAROPA_LINTS_WORKER_DEBUG=1 to see what workers report.
        messageSink: io.Platform.environment['SAROPA_LINTS_WORKER_DEBUG'] == '1'
            ? (m) => io.stderr.writeln('[worker] $m')
            : (_) {},
        applyExclusionsToFileList: false,
        excludeLightLane: spec.excludeLightLane,
        bypassTierCap: spec.bypassTierCap,
        lane: spec.laneIsLight ? RuleLane.light : RuleLane.full,
        noExclude: spec.noExclude,
        excludeGlobs: spec.excludeGlobs,
        includeGlobs: spec.includeGlobs,
        leaveStopSentinel: true,
      );
      return runner.openChunkScanner(
        resolved: spec.resolved,
        slowFileMs: spec.slowFileMs,
        rescueExcluded: spec.rescueExcluded,
      );
    }),
  );
}

/// Tunables for [ScanRunner.runParallel] beyond the worker count.
class ScanParallelConfig {
  const ScanParallelConfig({
    this.maxMemoryMb,
    this.reserveMb,
    this.availableMemoryMb,
    this.totalMemoryMb,
    this.chunkTimeout = const Duration(seconds: 120),
    this.slowFileMs = 3000,
    this.progress = ProgressStyle.auto,
    this.hasTerminal = false,
    this.chunkSize,
    this.forceEngine = false,
  });

  /// RSS budget for the whole scan process; null = derived from worker count
  /// and available memory.
  final int? maxMemoryMb;

  /// Free system memory to leave untouched; null = 10% of RAM (512–2048 MB).
  final int? reserveMb;

  /// Machine figures used to derive defaults.
  final int? availableMemoryMb;
  final int? totalMemoryMb;

  /// Per-chunk wall-clock limit before a worker is restarted.
  final Duration chunkTimeout;

  /// Files slower than this are reported.
  final int slowFileMs;

  final ProgressStyle progress;
  final bool hasTerminal;
  final int? chunkSize;

  /// Run through the engine even for one worker (gains timeouts, slow-file
  /// and memory watchdog; costs one worker-startup).
  final bool forceEngine;
}
